using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: HasData with DateTime.UtcNow is non-deterministic and
        // causes new migrations on every run. Use a fixed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking change fixes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfAppDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change (EF Core 9): Cosmos provider now uses "$type" instead of
        // "Discriminator" by default. For existing documents that already store
        // "Discriminator", explicitly configure the property name to keep compatibility.
        modelBuilder.Entity<Product>(b =>
        {
            b.HasDiscriminatorInJsonProperty("Discriminator");
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

// --- Cosmos query service demonstrating sync→async migration ---

class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // Breaking change (EF Core 9): Synchronous I/O on the Cosmos provider now throws
    // by default. All queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.)
    public async Task<List<Product>> GetProductsByCategoryAsync(string category)
    {
        return await _db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    public async Task<Product?> GetProductByIdAsync(string id)
    {
        return await _db.Products
            .FirstOrDefaultAsync(p => p.Id == id);
    }
}

