arguments.new_str:
using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    void ApplyMigrations(AppDbContext db)
    {
        // Breaking change (EF Core 9): Migrate() can no longer be called inside a
        // manual transaction — it now uses its own migration-scoped transaction.
        // Remove the wrapping BeginTransaction/Commit.
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

